var ps=UnityEngine.GameObject.Find("SurvivorPlayer");var sr=ps==null?null:ps.GetComponentInChildren<UnityEngine.SpriteRenderer>();var objs=new System.Collections.Generic.List<object>();foreach(var go in UnityEngine.Object.FindObjectsByType<UnityEngine.GameObject>(UnityEngine.FindObjectsSortMode.None)){if(!go.scene.IsValid())continue;if(go.name=="BuildingVisuals"||go.name=="ObstacleTilemap"||go.name=="GameplayTilemap"||go.name=="GroundDetailTilemap")objs.Add(new{name=go.name,pos=go.transform.position.ToString()});}return new{playerSpriteOrder=sr==null?-1:sr.sortingOrder,objects=objs};
